        chain, block,
        owner: contract,
        useDefaultCoreAssets: true,
        blacklist,
        tokens,
        cache,
      })
      await setCache(project, chain, cache)

      for (const [token, balance] of Object.entries(balances))
        sdk.util.sumSingleBalance(totalBalances, token, balance)
    }
    return totalBalances
  }
